"""Build the technical report from measured summaries and explicit assumptions."""
from pathlib import Path
import csv,html,json,shutil
import numpy as np
ROOT=Path(__file__).resolve().parents[1]
esc=html.escape

def build():
    audit=json.loads((ROOT/'results/summary/engineering_audit.json').read_text());b=audit['baseline']
    summaries={p.parent.name:json.loads(p.read_text()) for p in sorted((ROOT/'results/processed').glob('*/summary.json'))}
    def eq(s):return '<div class="math-display"><span class="math">'+esc(s)+'</span></div>'
    def fig(name,caption):return f'<figure><img class="report-figure" src="assets/images/{name}.png" alt="{esc(caption)}"><figcaption>{esc(caption)}</figcaption></figure>'
    def table(cases):
        rows=[]
        for c in cases:
            s=summaries[c];gamma=s['min_valid_gamma_deg'];recovery=s.get('stable_recovery_delay_s')
            rec='Not established' if recovery is None else f'{1000*recovery:.1f} ms'
            if c in ['CF-00','CF-01','CF-11','NUM-BASE-5US']:rec='No failure observed'
            rows.append(f'<tr><td><a href="#case-{c}">{c}</a></td><td>{s["verified_failure_events"]}</td><td>{s["inconclusive_events"]}</td><td>{s["peak_dc_current_A"]/1000:.3f}</td><td>{"N/A" if gamma is None else f"{gamma:.2f}"}</td><td>{rec}</td></tr>')
        return '<div class="table-wrap"><table><thead><tr><th>Case</th><th>Verified attempts</th><th>Inconclusive</th><th>Peak current (kA)</th><th>Minimum valid gamma (deg)</th><th>Stable sequence after clearing</th></tr></thead><tbody>'+''.join(rows)+'</tbody></table></div>'
    sections=[]
    def section(title,body):sections.append(f'<section class="card"><h2>{title}</h2>{body}</section>')
    section('1. Scope and evidence',f'''<p>This laboratory studies an independently built, standalone six-pulse line-commutated HVDC inverter. A floating DC voltage equivalent supplies a smoothing reactor and six individually measured thyristors. A grounded three-phase Thevenin equivalent supplies commutating voltage. There is no rectifier station, DC transmission line, transformer, PLL, or complete HVDC control system.</p>
    <p><strong>{audit['total_executed']} accepted PSCAD simulations</strong> produced <strong>{audit['total_verified_failure_attempts']} verified failed firing attempts</strong> across independent recordings, including numerical and follow-up runs. This total is not a count of independent external disturbances. Every waveform originates in native PSCAD/EMTDC output; Python classifies and plots it, and the browser replays it.</p>
    <p>The campaign contains CF-00 through CF-14, coarse and refined sag sweeps, inception-time variation, two 5 microsecond runs, matched mitigations, and recovery follow-ups. An initial model with an incorrect grounded DC return was rejected and excluded from these totals. The corrected model satisfies both upper- and lower-group current balance.</p>
    <p class="note">Public release source: <a href="https://github.com/angelohafner/hvdc-lcc-commutation-failure-lab">GitHub repository</a>. The <a href="https://angelohafner.github.io/hvdc-lcc-commutation-failure-lab/">online laboratory</a> replays the same recordings as the offline package. Deployment checks are recorded separately from native simulation validation.</p>''')
    section('2. Six-pulse operation and polarity', '''<p>The upper group is T1 (phase A), T3 (B), and T5 (C), carrying current from a phase toward P. The lower group is T4 (A), T6 (B), and T2 (C), carrying current from N toward a phase. The DC source is positive at N and negative at its reactor/resistor return. P and N float relative to ground. The source delivers energy while the bridge voltage P minus N is negative and the defined DC current is positive.</p>
    <img class="report-figure" src="assets/svg/inverter.svg" alt="Original inverter circuit with native SCR and IEEE resistor symbols">
    <p>The firing sequence is T1, T2, T3, T4, T5, T6, repeating every cycle with 60 electrical degrees between commands. Transfers within either valve group are 120 degrees apart. A valve normally carries current for about 120 degrees, with finite overlap at each transfer. Two valves conduct away from overlap; three share current during a normal transfer. Gate command and measured conduction are displayed separately.</p>
    <p>Phase A source voltage is sinusoidal at zero phase. T1 fires at 30 degrees plus its firing-angle reference. The controller uses sustained 120-degree gate windows and a fixed frequency clock. Source phase jumps do not instantaneously shift that clock. These choices are part of the experiment, not an industrial firing implementation.</p>'''+eq(r'P_{DC\rightarrow bridge}=-v_{PN}i_d,\qquad P_{PCC\rightarrow grid}=-\sum_{k=a,b,c}v_{PCC,k}i_{g,k}')+'''<p>Grid source current is measured positive toward the PCC, hence the minus sign in exported AC power. Positive values of both reported powers establish inverter operation.</p>''')
    section('3. Why commutation succeeds or fails', '''<p>Firing makes the incoming thyristor eligible to carry current. The voltage difference between its phase and the outgoing phase drives current through the two participating commutation inductances. Current cannot change instantly. During overlap, outgoing current falls while incoming current rises. For the upper group the driving voltage is incoming-phase PCC voltage minus outgoing-phase PCC voltage; the lower-group sign is reversed.</p>'''+eq(r'\int_{t_f}^{t_c}v_{comm}(t)\,dt\approx 2L_c I_d')+'''<p>This area relation is an ideal illustration with approximately constant DC current and equal phase inductances. The actual network includes source impedance, changing current, and coupled phase voltages, so event classification uses measured waveforms instead of this approximation.</p>'''+eq(r'\beta=180^\circ-\alpha,\quad \gamma=\beta-\mu,\quad \gamma_{meas}=360f(t_{forward}-t_{reverse})')+'''<p>Alpha measures firing delay from natural commutation, beta is the corresponding advance, mu spans firing to outgoing-current extinction, and gamma is the outgoing valve's reverse-bias interval. The identity gamma = 180 - alpha - mu assumes a successful transfer and the balanced sinusoidal reference. Under faults or phase jumps, the measured interval is authoritative. Missing intervals are not filled with an invented angle.</p>
    <p>A voltage sag reduces available driving area. A phase jump can move the voltage zero crossing. Larger DC current requires more current transfer. Source inductance prolongs overlap and alters PCC voltages. Harmonics reshape voltage area and zero crossings; they do not guarantee failure. A failure may retain outgoing current throughout the attempt, or may include extinction followed by resumed conduction.</p>'''+fig('normal_vs_failed','The same T3 to T5 transfer in normal operation and the 50% sag, aligned at firing with common vertical scales.'))
    nominal=json.loads((ROOT/'config/model_parameters.json').read_text())
    paramrows=[('AC network','100 kV line-to-line RMS, 50 Hz'),('Grid per phase','0.3 ohm + 10 mH'),('Commutation inductance','10 mH per phase; no transformer'),('DC source','118 kV, floating, negative at the reactor return'),('DC series branch','5 ohm + 0.5 H'),('Nominal firing reference','140 degrees'),('Native thyristors','master:peswitch, Type = thyristor; Ron = 0.01 ohm, Roff = 100 Mohm; snubber disabled'),('Minimum extinction time','200 microseconds (3.6 degrees at 50 Hz)'),('Main integration / recording step','10 microseconds; representative sensitivity runs at 5 microseconds'),('Initialization','DC voltage ramps from 0.02 to 0.10 s; event analysis starts at 0.22 s'),('Default event','0.30 to 0.38 s; simulations end at 0.60 s, with longer recovery/persistent runs')]
    section('4. PSCAD model, configuration and device limits','<table><tbody>'+''.join(f'<tr><th>{a}</th><td>{b}</td></tr>' for a,b in paramrows)+'</tbody></table>'+'''<p>The original controller and topology are stored in lcc_inverter.pscx; each experiment has its own LCC_*.pscx file. Installed PSCAD master components are referenced rather than redistributed. Native execution used PSCAD 5.1.0 Professional, mhi.pscad 3.1.2 and GFortran 8.1 (64-bit).</p>
    <p>PSCAD's documented thyristor uses on/off resistance and current-zero turn-off, with a minimum extinction-time rule that can re-fire the device if forward voltage returns too soon. Reverse recovery current is idealized. Therefore these results demonstrate the selected EMT model's switching behavior, not semiconductor charge storage, thermal stress, or a hardware recovery limit. See the <a href="https://www.pscad.com/webhelp-v502-ol/Master_Library_Models/HVDC_and_FACTS/PE_Switch/Thyristor.htm">official thyristor model documentation</a>.</p>
    <p>Frequency, AC voltage, grid R/L, commutation inductance, DC voltage/resistance/reactor, firing references, fault resistance/type/timing, harmonics and recovery profiles are configurable. Optional SCR, current-reference and gamma-reference inputs calculate balanced-sinusoidal feedforward estimates. They do not introduce feedback regulation; measure the resulting operating point after running PSCAD.</p>'''+eq(r'\mathrm{SCR}=\frac{V_{LL}^{2}}{P_{base}\sqrt{R_g^2+(2\pi fL_g)^2}},\qquad P_{base}=150\ \mathrm{MW}')+'''<p>SCR is approximately 21.12 for the nominal source and 3.54 for the weak-grid case. Commutation inductance is excluded from this source-SCR definition. Zero-sequence paths follow the independently grounded phase sources; the model does not reproduce a particular transformer winding connection.</p>''')
    section('5. Baseline validation',f'''<p>Over 0.50-0.60 s, mean DC current is {b['mean_idc_A']/1000:.4f} kA, bridge voltage is {b['mean_vdc_V']/1000:.3f} kV, DC power into the bridge is {b['mean_pdc_W']/1e6:.3f} MW and AC power into the grid at the PCC is {b['mean_pac_W']/1e6:.3f} MW. Current ripple is {100*b['peak_to_peak_current_fraction']:.2f}% peak-to-peak; the change among four successive cycle means is {100*b['cycle_mean_drift_fraction']:.4f}%.</p>
    <p>All 112 analyzed baseline attempts complete normally. The gate sequence is correct. Recorded gate width ranges from {b['gate_width_deg_min']:.2f} to {b['gate_width_deg_max']:.2f} degrees because of sample quantization. Late-record measured overlap is {b['mean_overlap_deg']:.2f} degrees and minimum reverse-bias interval is {b['min_gamma_deg']:.2f} degrees. The ideal angle balance closes within sampling and threshold resolution.</p>
    <p>The disturbance comparisons share the same initialization. The 0.22-0.28 s pre-event current is still approaching its final value (about 1.245 kA versus 1.292 kA late in the baseline). This residual initialization drift is disclosed rather than called exact steady state at fault inception.</p>'''+fig('CF-00_selected_commutation','Measured successful current transfer, valve reverse voltage, driving voltage and gate commands.'))
    section('6. Classification and counting rules','''<p>One record is created per incoming gate rising edge after 0.22 s. The window ends just before the next recorded gate edge in that valve group, including extra edges caused by reference changes. Already-established incoming conduction, a missing sustained post-gate current rise, or simultaneous group commands make the attempt inconclusive. The initially dominant measured current identifies the actual outgoing valve; a different outgoing valve than expected is flagged as an abnormal sequence.</p>
    <ul><li><strong>Successful / reduced margin:</strong> outgoing current crosses the off threshold and establishes reverse voltage, the incoming valve carries current, a sustained reverse-voltage interval is measured, and outgoing current does not resume within the observation window. Less than 15 degrees is labeled reduced margin, not automatically failure.</li>
    <li><strong>Unsuccessful transfer:</strong> incoming current rises after a gate command, outgoing current never falls below its off threshold, and PCC driving voltage becomes negative while the outgoing valve remains conducting.</li>
    <li><strong>Resumed conduction:</strong> outgoing current falls below threshold, sustained reverse voltage is observed, and substantial outgoing current returns with a conducting valve voltage, without a new outgoing gate edge.</li>
    <li><strong>Inconclusive:</strong> evidence is missing, ambiguous, discontinuous, or outside the complete observation window. A near-zero current dip without reverse voltage is insufficient to establish resumed conduction.</li></ul>
    <p>The off threshold is the larger of 10 A and 2% of window median DC current; established conduction uses the larger of 50 A and 10%. Voltage tests use -500 V for reverse bias, +500 V for returning forward voltage, and -1 kV for driving-voltage reversal. Conditions persist for three samples. Incoming current must initially be below the established-conduction threshold and then rise above its initial value by that threshold. A current-threshold crossing is stored separately; reported completion and overlap require reverse-voltage evidence. These conservative engineering thresholds, finite windows and sampling affect event counts; counts are not universal fault probabilities. The browser's smaller ON-display threshold (1 A or 0.1% of instantaneous DC current) is separate and shown beside the valve readings.</p>
    <p>Six consecutive successful attempts after clearing establish an observed recovery. A later verified failure marks one recurrence episode. Intervening inconclusive attempts do not erase the earlier successful interval, but they interrupt evidence of continuous stable operation. Stable recovery is reported only when at least six consecutive successful attempts continue through the last fully analyzable event; the final partial window is excluded.</p>''')
    section('7. Campaign outcomes',table(list(summaries))+'''<p>Minimum gamma is taken only from valid measured intervals anywhere in the analyzed record, including before the disturbance. It is not a gamma estimate for failed transfers. Stable-sequence delay is measured from clearing, and does not require nominal power or nominal current to have returned.</p>''')
    descriptions={
      'CF-00':'Undisturbed reference used to establish inverter operation.',
      'CF-01':'Alpha is 150 degrees and DC source voltage is 131.2 kV, maintaining a comparable current. All transfers succeed at a reduced margin. This is not a one-variable alpha comparison.',
      'CF-02':'The source voltage is 0.50 pu during the event. The first failure is T3 to T5 at 0.30278 s; driving voltage reverses near 0.30508 s while T3 current remains positive. T5 current rises and then collapses; T3 never establishes reverse voltage.',
      'CF-03':'A-to-ground fault at the PCC through 2 ohm. Phase A commutation pairs are directly affected.',
      'CF-04':'A-to-B fault through 2 ohm at the PCC reduces the voltage available to that phase pair.',
      'CF-05':'B- and C-to-ground faults, each through 2 ohm, affect multiple line-to-line voltages.',
      'CF-06':'Three-phase ground fault through 0.2 ohm per phase. A selected event includes reverse voltage followed by resumed conduction within about 180 microseconds, consistent with the configured simplified recovery-time rule.',
      'CF-07':'A -25 degree source phase jump is applied and removed with the event; the fixed firing clock is unchanged. No PLL dynamics are represented.',
      'CF-08':'The DC source driving voltage increases by 30%, raising current indirectly. This is not a prescribed ideal-current-source step.',
      'CF-09':'The firing reference is delayed to 168 degrees during the event. The loss of advance creates actual unsuccessful transfers; failure is not assigned from the reference angle alone.',
      'CF-10':'Grid inductance increases to 60 mH and a 0.8 pu sag is applied. Its pre-event current differs substantially from nominal; this is an illustrative weak-grid case, not a controlled proof that SCR alone causes a specific failure count.',
      'CF-11':'A fifth harmonic of 0.25 pu of the fundamental source peak is added during the event. This tested distortion produces no verified failures; it lowers the valid margin, but more severe or different harmonics were not established.',
      'CF-12':'A 0.3 pu source sag lasts 120 ms. Multiple distinct incoming firing attempts fail during one disturbance and continuing abnormal operation.',
      'CF-13':'The initial 0.35 pu sag experiment remains in continuing failure after clearing. It does not establish recovery followed by recurrence. Follow-up CF-13-R2 below supplies the controlled subsequent-failure example.',
      'CF-14':'A 0.15 pu sag lasts 250 ms. High current and abnormal conduction persist after the first verified failure; later individual attempts are inconclusive under the conservative detector. There is no protection blocking logic, so the state is not called converter blocking.'}
    details=[]
    for c,s in summaries.items():
        ev=json.loads((ROOT/f'results/processed/{c}/events.json').read_text());p=json.loads((ROOT/f'results/processed/{c}/metadata.json').read_text())['parameters'];first=next((e for e in ev if e['verified_failure']),None)
        desc=descriptions.get(c,s['title']+'. See the parameter manifest for the exact native configuration.')
        evidence=('No verified failure in the analyzed record.' if first is None else f'First verified attempt: {first["event_id"]}, {first["outgoing"]} to {first["incoming"]}, gate at {first["time_s"]:.5f} s; '+ ' '.join(first['evidence'])+'.')
        details.append(f'<article id="case-{c}"><h3>{c}: {esc(s["title"])}</h3><p>{esc(desc)}</p><p>{esc(evidence)} Final mean current is {s["mean_dc_current_final_A"]/1000:.3f} kA. {s["post_clearing_failure_events"]} verified attempts occur after clearing; {s["subsequent_failure_events"]} begin a verified recurrence episode after an established recovery interval.</p></article>')
    section('8. Case-by-case physical interpretation',''.join(details)+fig('resumed_conduction','CF-06: measured current extinction and a brief reverse-voltage interval followed by resumed conduction.'))
    section('9. Repeated failure and recovery',fig('CF-12_event_timeline','Each marker represents one incoming firing attempt; multiple signals do not create duplicate events.')+'''<p>CF-13-R2 uses the same 50% AC sag as CF-02. After clearing at 0.38 s, a prescribed external DC-equivalent command reverses to -0.2 pu for 120 ms to force current suppression. This is an aggressive ideal source action, not a validated rectifier controller or VDCOL. At 0.50 s the command restores toward nominal with a temporary overshoot:</p>'''+eq(r'k_{DC}(u)=1+e^{-u/0.15}\left(1-e^{-u/0.10}\right),\quad u=t-0.50\ge0')+'''<p>Successful attempts begin at 0.50612 s; the sixth confirms recovery at 0.52278 s. A later verified failed T5-to-T1-group sequence is identified from the event record below (the selected incoming and outgoing labels in the figure are authoritative). The first verified recurrence fires at 0.57278 s. No second AC fault is applied. The matched REC-NOMINAL run uses the same current-suppression interval but restores to exactly nominal voltage and maintains successful commutation.</p>
    <p>The weaker suppression in CF-13-R1 and REC-SMOOTH does not restore commutation. These unsuccessful trials are retained to show that clearing alone and insufficient DC reduction do not guarantee recovery.</p>'''+fig('recovery','Matched recovery commands: the restoration transient produces recurrence; nominal restoration maintains recovery.')+fig('subsequent_detail','Valve-level evidence for the first verified failure after an established recovery interval in CF-13-R2.'))
    # Derive the valve labels rather than rely on an explanatory assumption.
    recurrence=next(e for e in json.loads((ROOT/'results/processed/CF-13-R2/events.json').read_text()) if e.get('subsequent_after_recovery'))
    sections[-1]=sections[-1].replace('T5-to-T1-group sequence is identified from the event record below (the selected incoming and outgoing labels in the figure are authoritative)',f'{recurrence["outgoing"]}-to-{recurrence["incoming"]} transfer is identified from the event record below')
    section('10. Mitigation, sensitivity and tradeoffs',fig('mitigation','Same 50% sag and same initial source settings: compare firing advance, DC source reduction and the unmitigated case.')+'''<p>MIT-ANGLE advances the reference to 120 degrees during the sag. MIT-DC sets the DC source to 0.35 pu during the sag. MIT-COMBINED uses 125 degrees and 0.65 pu DC voltage. DC reduction prevents verified failures in the tested case and limits peak current to about 1.30 kA, but includes 14 inconclusive, low/discontinuous-current attempts and temporarily reduces power. Firing advance alone does not ensure recovery. These commands are scheduled from the event timer; no voltage-dependent current limiter or closed-loop gamma controller is implemented.</p>
    <p>The coarse retained-voltage sweep includes 0.50, 0.65, 0.80 and 0.90 pu. Refined runs at 0.85 and 0.875 pu bracket a change from verified failures to none. This is a sampled boundary for an 80 ms event, the specified initialization and inception, fixed source settings and a 10 microsecond step; it is not a universal critical voltage. A 5 ms inception shift (90 electrical degrees) changes the recorded sequence and failure count. A 10 ms sag still leads to sustained abnormal current in this source equivalent.</p>'''+table(['CF-02','MIT-ANGLE','MIT-DC','MIT-COMBINED','CF-13-R2','REC-NOMINAL'])+'''<p>Halving the time step from 10 to 5 microseconds preserves the baseline zero-failure result and the sag's 30 verified attempts. The baseline peak current changes by about 0.766%; the sag peak changes by 0.00233%. The first sag failure evidence time is unchanged, while minimum valid gamma differs by 0.09 degrees. Two time steps provide sensitivity evidence, not a complete convergence proof.</p>''')
    section('11. Reproduction, provenance and browser use','''<p>Native .inf/.out files and execution receipts are retained locally under results/raw. Shareable PSCAD copies redact OS-account author stamps only; release_project_hashes.json maps their hashes to the unchanged executed archives. SHA-256 hashes, timestamps, project filenames, PSCAD/compiler versions and channel units accompany processed outputs. The reader rejects invalid timing, hash mismatches, missing channels, non-finite values and incomplete durations. Processed arrays use SI units; two power channels are derived from measured voltages and currents. All 38 native channels remain available in the processed NPZ files.</p>
    <p>Browser datasets retain every native sample from 0.20 s onward. Values are converted to float32, losslessly compressed, and decoded locally. Each case declares its maximum float-conversion error per signal. Overview drawing retains local extrema; event details use native samples. The website loads only selected cases. The two numerical sensitivity runs remain in the engineering results rather than the student selector.</p>
    <p>Open index.html in a modern Chrome or Edge browser. Direct file opening was tested. Alternatively run the command below from the project root and open http://127.0.0.1:8765/. No PSCAD installation is needed for the learning pages. To reproduce simulations, install the Python requirements, open licensed PSCAD 5.1.0, determine its automation port and use the scripts below. See README.md for the complete sequence and the distinction between new execution and reprocessing.</p>
    <pre>py -3.11 -m http.server 8765 --bind 127.0.0.1 --directory docs
py -3.11 python/check_environment.py --port YOUR_PORT
py -3.11 python/run_simulations.py --port YOUR_PORT --cases CF-00 CF-02
py -3.11 python/process_results.py CF-00 CF-02
py -3.11 python/generate_plots.py CF-00 CF-02
py -3.11 python/export_html_data.py</pre>
    <p>Existing raw evidence is never overwritten. Use a clean results directory in a separate reproduction copy, or a new case identifier through the Python API. Final browser checks cover all eight modules, desktop/mobile layouts, controls, rendered equations, assessment feedback, exports and direct file opening. Source-profile validation checks each AC phase and the DC source independently in 97 pre-event, disturbance, suppression and restoration segments. Segment medians must remain below 1,000 V after excluding 1 ms at each boundary. Contradictory returned-current evidence remains inconclusive. Publication checks and audit resolutions are recorded in reports/publication_audit.md in the source repository.</p>''')
    section('12. Limitations and conclusions','''<p>The study establishes a physically consistent normal inverter operating point, unsuccessful current transfer under several disturbances, model-level resumed conduction, repeated failure attempts, and a controlled recovery-then-recurrence example. It also includes reduced-margin and harmonic cases without verified failure. The most useful educational evidence is the joint view of incoming current, outgoing current, valve voltage and driving voltage.</p>
    <p>The fixed and scripted DC equivalent can drive unrealistically persistent large current because it contains no rectifier current controller, protective blocking, current limit, or energy constraint. Such current levels illustrate this model's behavior and must not be used as equipment ratings. Network strength changes the initial current unless the operating point is recalibrated. The ideal firing clock, grounded AC source configuration, omitted transformer/filter/control dynamics, simplified semiconductor recovery, short observation periods, thresholds, and limited numerical study bound the conclusions.</p>
    <p>Use the eight laboratories to move from conduction sequence to commutation evidence, then compare disturbances and mitigation tradeoffs. Select parameters through recorded cases; the browser does not synthesize or interpolate new EMT responses.</p>''')
    section('13. References and licenses','''<ul><li><a href="https://www.pscad.com/software/pscad/automation-library">PSCAD Automation Library</a>: official automation entry point; installed API signatures were checked during construction.</li><li><a href="https://www.pscad.com/webhelp-pscad-v5.1.0-ol/Master_Library_Models/HVDC_and_FACTS/PE_Switch/peswitch.htm">PSCAD 5.1 power electronic switch</a>: component parameter reference.</li><li><a href="https://www.pscad.com/webhelp-v502-ol/Master_Library_Models/HVDC_and_FACTS/PE_Switch/Thyristor.htm">PSCAD thyristor behavior</a>: turn-on, current-zero turn-off and extinction-time assumptions.</li><li>Original project scripts, model topology, event detector, lessons and figures: MIT license. Bundled KaTeX and its fonts retain their license notices. PSCAD software and master libraries are not distributed.</li></ul>''')
    head='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Technical report | HVDC Commutation Failure Lab</title><link rel="stylesheet" href="assets/css/lab.css"><link rel="stylesheet" href="assets/vendor/katex/katex.min.css"><script defer src="assets/vendor/katex/katex.min.js"></script><style>article{break-inside:avoid;margin:25px 0}figure{margin:20px 0}figcaption{font-size:.85rem;color:#526d7e}h2{break-after:avoid}@media print{.card{break-inside:auto; border:0;padding:0;margin:20px 0}figure{break-inside:avoid}a{color:inherit}body[data-page=report] main{max-width:none}table{font-size:8pt}thead{display:table-header-group}.report-figure{max-height:235mm;object-fit:contain}h1{font-size:24pt}h2{font-size:16pt}p,li{font-size:10pt}pre{font-size:8pt}}</style></head><body data-page="report"><header class="topbar"><a class="brand" href="index.html">HVDC Commutation Failure Lab</a><a href="index.html">Open the laboratories</a></header><main><p class="eyebrow">Engineering report · Public edition · 16 November 2026</p><h1>HVDC-LCC inverter commutation failure</h1><p>Original PSCAD simulations, valve-level evidence and an interactive learning laboratory</p>'''
    tail='''</main><script>addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('.math').forEach(e=>katex.render(e.textContent,e,{throwOnError:false,displayMode:true}));});</script></body></html>'''
    (ROOT/'docs/technical_report.html').write_text(head+'\n'.join(sections)+tail,encoding='utf-8')
    (ROOT/'reports/technical_report.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta http-equiv="refresh" content="0;url=../docs/technical_report.html"><title>Technical report</title><a href="../docs/technical_report.html">Open the complete technical report</a></html>')
    out=ROOT/'results/summary/case_summary.csv'
    fields=['case_id','title','verified_failure_events','inconclusive_events','peak_dc_current_A','min_valid_gamma_deg','post_clearing_failure_events','subsequent_failure_events','stable_recovery_delay_s','mean_dc_current_final_A']
    with out.open('w',newline='',encoding='utf-8') as f:
        w=csv.DictWriter(f,fieldnames=fields,extrasaction='ignore');w.writeheader();w.writerows(summaries.values())
    print('Built technical report and case summary CSV')

if __name__=='__main__':build()
